17	/**
18	 * Forbids catching Throwable, Exception, and the LogicException and Error
19	 * families outside a configured boundary layer.
20	 *
21	 * Broad catches swallow programmer errors together with the failures they
22	 * meant to handle. Only designated boundary files (entry points, middleware,
23	 * worker loops) may catch these types.
24	 *
25	 * @implements Rule<\PhpParser\Node\Stmt\Catch_>
26	 */
27	final class ForbidBroadCatchRule implements Rule
28	{
29	    /** @readonly */
30	    private BroadCatchPathMatcher $pathMatcher;
31	
32	    /**
33	     * @param list<string> $broadCatchAllowedPaths fnmatch patterns of boundary files allowed to catch broadly
34	     */
35	    public function __construct(
36	        array $broadCatchAllowedPaths = [],
37	        ?BroadCatchPathMatcher $pathMatcher = null,
38	    ) {
39	        $this->pathMatcher = $pathMatcher ?? new BroadCatchPathMatcher($broadCatchAllowedPaths);
40	    }
41	
42	    /**
43	     * @return class-string<\PhpParser\Node\Stmt\Catch_>
44	     */
45	    public function getNodeType(): string
46	    {
47	        return \PhpParser\Node\Stmt\Catch_::class;
48	    }
49	
50	    /**
51	     * @param \PhpParser\Node\Stmt\Catch_ $node
52	     * @return list<IdentifierRuleError>
53	     */
54	    public function processNode(\PhpParser\Node $node, Scope $scope): array
55	    {
56	        if ($this->pathMatcher->isAllowed($scope->getFile())) {
57	            return [];
58	        }
59	
60	        $errors = [];
61	        foreach ($node->types as $typeName) {
62	            $writtenName = $typeName->toString();
63	            $className = $scope->resolveName($typeName);
64	            $lowerClassName = strtolower($className);
65	
66	            if ($lowerClassName === 'throwable' || $lowerClassName === 'exception') {
67	                $reason = sprintf('catch (%s) intercepts every failure, including programmer errors', $writtenName);
68	            } elseif ((new ObjectType('LogicException'))->isSuperTypeOf(new ObjectType($className))->yes()) {
69	                $reason = sprintf('%s is a programmer error (LogicException family) that must be fixed at its source, not caught', $writtenName);
70	            } elseif ((new ObjectType('Error'))->isSuperTypeOf(new ObjectType($className))->yes()) {
71	                $reason = sprintf('%s is an engine failure (Error family) that must be fixed at its source, not caught', $writtenName);
72	            } else {
73	                continue;
74	            }
75	
76	            $errors[] = RuleErrorBuilder::message(
77	                sprintf(
78	                    'Catch a specific exception type instead of "%s": %s. If this catch is an intentional top-level boundary handler, add its file path to customRules.broadCatchAllowedPaths.',
79	                    $writtenName,
80	                    $reason
81	                )
82	            )
83	                ->identifier('customRules.broadCatch')
84	                ->line($node->getStartLine())
85	                ->build();
86	        }
87	
88	        return $errors;
89	    }
90	}
