16	/**
17	 * Detects PHPUnit assertInstanceOf() calls guaranteed by static types.
18	 */
19	final class AssertInstanceOfRedundancyInspector
20	{
21	    /** @readonly */
22	    private CallMethodNameResolver $methodNameResolver;
23	
24	    /** @readonly */
25	    private CallArgumentResolver $argumentResolver;
26	
27	    /** @readonly */
28	    private ClassStringExpressionResolver $classStringResolver;
29	
30	    /** @readonly */
31	    private PhpUnitCallTargetMatcher $targetMatcher;
32	
33	    /** @readonly */
34	    private NoRedundantAssertInstanceOfErrorBuilder $errorBuilder;
35	
36	    /** @readonly */
37	    private AssertInstanceOfTypeMatcher $typeMatcher;
38	
39	    /**
40	     * Creates an inspector from call parsing and error-building collaborators.
41	     */
42	    public function __construct(
43	        ?CallMethodNameResolver $methodNameResolver = null,
44	        ?CallArgumentResolver $argumentResolver = null,
45	        ?ClassStringExpressionResolver $classStringResolver = null,
46	        ?PhpUnitCallTargetMatcher $targetMatcher = null,
47	        ?NoRedundantAssertInstanceOfErrorBuilder $errorBuilder = null,
48	        ?AssertInstanceOfTypeMatcher $typeMatcher = null,
49	    ) {
50	        $this->methodNameResolver = $methodNameResolver ?? new CallMethodNameResolver();
51	        $this->argumentResolver = $argumentResolver ?? new CallArgumentResolver();
52	        $this->classStringResolver = $classStringResolver ?? new ClassStringExpressionResolver();
53	        $this->targetMatcher = $targetMatcher ?? new PhpUnitCallTargetMatcher();
54	        $this->errorBuilder = $errorBuilder ?? new NoRedundantAssertInstanceOfErrorBuilder();
55	        $this->typeMatcher = $typeMatcher ?? new AssertInstanceOfTypeMatcher();
56	    }
57	
58	    /**
59	     * @return list<IdentifierRuleError>
60	     */
61	    public function errors(\PhpParser\Node\Expr $node, Scope $scope): array
62	    {
63	        if ($node instanceof \PhpParser\Node\Expr\MethodCall) {
64	            if (!$this->targetMatcher->isThisMethodCall($node)) {
65	                return [];
66	            }
67	
68	            return $this->errorsForCall(
69	                $this->methodNameResolver->resolve($node->name),
70	                $node->args,
71	                $node->getStartLine(),
72	                $scope,
73	            );
74	        }
75	
76	        if ($node instanceof \PhpParser\Node\Expr\StaticCall) {
77	            if (!$this->targetMatcher->isStaticCallOnPhpUnitAssert($node, $scope)) {
78	                return [];
79	            }
80	
81	            return $this->errorsForCall(
82	                $this->methodNameResolver->resolve($node->name),
83	                $node->args,
84	                $node->getStartLine(),
85	                $scope,
86	            );
87	        }
88	
89	        return [];
90	    }
91	
92	    /**
93	     * @param array<array-key, \PhpParser\Node\Arg|\PhpParser\Node\VariadicPlaceholder> $args
94	     * @return list<IdentifierRuleError>
95	     */
96	    public function errorsForCall(?string $methodName, array $args, int $line, Scope $scope): array
97	    {
98	        if ($methodName !== 'assertInstanceOf') {
99	            return [];
100	        }
101	
102	        $expectedExpression = $this->argumentResolver->valueAt($args, 0);
103	        $actualExpression = $this->argumentResolver->valueAt($args, 1);
104	        if ($expectedExpression === null || $actualExpression === null) {
105	            return [];
106	        }
107	
108	        $expectedTypeName = $this->classStringResolver->resolve($expectedExpression, $scope);
109	        if ($expectedTypeName === null) {
110	            return [];
111	        }
112	
113	        $actualType = $scope->getType($actualExpression);
114	        $actualTypeNames = $actualType->getObjectClassNames();
115	        if (count($actualTypeNames) !== 1) {
116	            return [];
117	        }
118	
119	        if (!$this->typeMatcher->matches($expectedTypeName, $actualType, $actualTypeNames[0])) {
120	            return [];
121	        }
122	
123	        return [$this->errorBuilder->build($actualTypeNames[0], $expectedTypeName, $line)];
124	    }
125	}
